// ---------------------------------------------------------------------------
// Crash-safe spawn + robust git-binary resolution (mt#2810)
// ---------------------------------------------------------------------------
//
// ## The incident
//
// Four `session_pr_merge` PreToolUse gates (require-review-before-merge,
// require-execution-evidence-before-merge, require-deploy-verification-
// before-merge, block-out-of-band-merge) all crashed with
// `ENOENT: posix_spawn 'git'` from the shared `pr-context.ts` fetch layer
// (`deriveRepoFromGit` -> `execWithPath` -> `Bun.spawnSync(["git", ...])`),
// on two separate days (2026-07-14 in a session workspace, 2026-07-15 in
// the main repo). Per each gate's documented fail-open posture, a hook that
// crashes before writing a `permissionDecision` is indistinguishable from
// one that ran and allowed — so the merges were silently permitted with
// ZERO gate enforcement, invisible to both agent and user, and the only
// trace was a raw uncaught-exception stack trace instead of a diagnosable
// warning.
//
// ## Two independent bugs, two independent fixes
//
// 1. **`Bun.spawnSync` THROWS on ENOENT instead of returning a failed
//    result.** Verified directly: `Bun.spawnSync(["git", ...], { env: {
//    PATH: "/nonexistent" } })` throws a synchronous `Error: Executable not
//    found in $PATH: "git" { code: "ENOENT", path: "git", errno: -2 }`
//    rather than returning `{ exitCode: <nonzero>, ... }`. Neither the
//    pre-mt#2810 `execSync` nor `execWithPath` wrapped the call in
//    try/catch, despite this file's own header comment claiming the
//    opposite ("spawnSync wrapper that returns { exitCode, stdout, stderr }
//    WITHOUT THROWING") — the comment described the intended contract; the
//    implementation didn't deliver it. `safeSpawnSync` below is the actual
//    fix: it catches ANY spawn-time throw (missing binary, exec permission
//    denied, etc.) and returns a synthetic non-zero `ExecResult` instead,
//    so a spawn failure degrades exactly like a normal non-zero command
//    exit — which every caller in this codebase (starting with
//    `deriveRepoFromGit` in `pr-context.ts`) already handles gracefully.
//    It also logs a loud `console.error` naming the failed command, so the
//    failure is visible in the hook's own stderr even for a caller (like
//    `require-review-before-merge.ts`, pre-mt#2810) that has no warning
//    path of its own for this branch.
//
// 2. **WHY the hook spawn env lacked PATH (root-cause finding, documented
//    per mt#2810 acceptance criteria).** `execWithPath`'s PATH augmentation
//    was `/opt/homebrew/bin:/usr/local/bin:${process.env.PATH ?? ""}` — it
//    assumes git lives under one of those two hardcoded prefixes, OR that
//    `process.env.PATH` (the hook subprocess's OWN inherited PATH, set by
//    whatever spawned the hook — Claude Code's main-agent process, or a
//    dispatched/backgrounded subagent's harness) already contains git's
//    location. Neither is guaranteed for every hook-spawn context:
//      - A dispatched/backgrounded subagent process is not guaranteed to
//        inherit the same interactive-shell PATH the main agent has (login
//        shells source `.zshrc`/`.zprofile`, which is what actually adds
//        Homebrew to `PATH` on a fresh shell — a non-interactive subprocess
//        spawn can plausibly skip that and hand the hook a minimal PATH).
//      - Even a well-formed inherited PATH can point at a distro layout
//        the hardcoded two-entry prefix doesn't anticipate (e.g. Debian/
//        Ubuntu's default `/usr/bin/git`, which this file's prefix did NOT
//        special-case — it relied entirely on `process.env.PATH` already
//        containing `/usr/bin`).
//    Net effect: `execWithPath`'s augmentation is a PATH *prefix*, not a
//    binary *resolution* strategy — it never actually asks "does a `git`
//    executable exist," it just hopes one of a few directories is both
//    present in the final PATH string AND contains git. `resolveGitBinary`
//    below replaces that hope with an actual resolution: `Bun.which`
//    first (respects whatever real PATH is present), then a filesystem
//    existence check against a short list of standard install locations
//    (no subprocess spawn, so this step can't itself throw ENOENT) — and
//    only falls through to the bare, unresolved `"git"` (still crash-safe
//    via `safeSpawnSync`) if truly nothing is found anywhere.

/** Options accepted by `Bun.spawnSync`'s `env` field. */
type SpawnEnv = Record<string, string | undefined>;

/** The structured result every exec helper in this module returns. Never thrown past. */
export interface ExecResult {
  exitCode: number;
  stdout: string;
  stderr: string;
  timedOut?: boolean;
}

/** Options `safeSpawnSync` hands to its spawn impl (a subset of Bun's `SpawnOptions`). */
export interface SpawnSyncCallOptions {
  cwd?: string;
  stdout: "pipe";
  stderr: "pipe";
  timeout?: number;
  env?: SpawnEnv;
}

/** The subset of `Bun.spawnSync`'s return shape `safeSpawnSync` actually reads. */
export interface SpawnSyncResultLike {
  exitCode: number | null;
  stdout: { toString(): string };
  stderr: { toString(): string };
}

/**
 * An injectable stand-in for `Bun.spawnSync` (mt#3630). Production always uses the
 * real one; tests pass a fake (or a thrower, for the mt#2810 ENOENT contract) instead
 * of patching the global, so no test mutates `Bun` for the whole runner process.
 */
export type SpawnSyncImpl = (cmd: string[], options: SpawnSyncCallOptions) => SpawnSyncResultLike;

/**
 * Sink for the loud `[hook-exec] DEGRADED` warning (mt#2810's structured-warning
 * criterion). Defaults to `console.error`; injectable (mt#3630) so a test asserts on
 * the captured message instead of silencing the real console with a spy.
 */
export type DegradedSink = (message: string) => void;

/** Test-only injection points shared by every exec helper here (mt#3630). */
export interface ExecInjection {
  /** Injectable `Bun.spawnSync` — production defaults to the real one. */
  spawnSyncImpl?: SpawnSyncImpl;
  /** Injectable degradation sink — production defaults to `console.error`. */
  onDegraded?: DegradedSink;
}

/** Options accepted by `execSync` / `execWithPath`. */
export interface ExecOptions extends ExecInjection {
  cwd?: string;
  timeout?: number;
}

const realSpawnSync: SpawnSyncImpl = (cmd, options) => Bun.spawnSync(cmd, options);

/**
 * Forward only the injection fields a caller actually supplied (PR #2580 R1
 * NON-BLOCKING). Every exec helper funnels its DI through this ONE place, so adding a
 * future injection point is a single edit here rather than a per-helper conditional
 * spread. Conditional rather than unconditional so an absent field stays absent instead
 * of becoming an explicit `undefined` — which would defeat the `??` defaults below.
 */
function execInjection(options?: ExecInjection): ExecInjection {
  return {
    ...(options?.spawnSyncImpl ? { spawnSyncImpl: options.spawnSyncImpl } : {}),
    ...(options?.onDegraded ? { onDegraded: options.onDegraded } : {}),
  };
}

/**
 * Spawn a command synchronously WITHOUT throwing on failure to resolve or
 * exec the binary (mt#2810 fix #1 — see the module comment above). Every
 * exec helper in this module funnels through here so a spawn failure
 * (missing binary, permission denied, etc.) always degrades to a
 * structured `ExecResult` instead of crashing the hook process, and always
 * logs a loud, structured warning naming the exact command that failed to
 * spawn — visible in the hook's own stderr regardless of whether the caller
 * has its own fail-open warning path.
 *
 * `spawnSyncImpl` / `onDegraded` are test-only DI (mt#3630) defaulting to the real
 * `Bun.spawnSync` and `console.error`; production call sites pass neither.
 */
function safeSpawnSync(
  cmd: string[],
  options: { cwd?: string; timeout?: number; env?: SpawnEnv } & ExecInjection
): ExecResult {
  const spawnSyncImpl = options.spawnSyncImpl ?? realSpawnSync;
  const onDegraded = options.onDegraded ?? ((message: string) => console.error(message));
  try {
    const result = spawnSyncImpl(cmd, {
      cwd: options.cwd,
      stdout: "pipe",
      stderr: "pipe",
      timeout: options.timeout,
      ...(options.env ? { env: options.env } : {}),
    });
    // mt#2810 PR #1952 R1 NON-BLOCKING: broadened from `signalCode ===
    // "SIGTERM"` — a timed-out `Bun.spawnSync` always reports `exitCode:
    // null` (it never completed normally), but the signal Bun uses to kill
    // it can vary by platform/version (e.g. SIGKILL after a grace period).
    // Gating on SIGTERM specifically produced a false negative (`timedOut:
    // false`) for any of those other signals. `exitCode === null` alone is
    // the reliable "did not exit normally" signal.
    const timedOut = result.exitCode === null;
    return {
      exitCode: result.exitCode ?? 1,
      stdout: result.stdout.toString().trim(),
      stderr: result.stderr.toString().trim(),
      timedOut,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    // Loud degradation signal (mt#2810 success criterion: "when git
    // genuinely cannot be resolved, emit a loud structured warning naming
    // the degradation — not a bare stack trace"). This is the lowest
    // common layer every gate's exec call funnels through, so it fires
    // regardless of which of the four gates (or future callers) triggered
    // it, and regardless of whether that caller has its own warning path.
    onDegraded(
      `[hook-exec] DEGRADED: failed to spawn \`${cmd.join(" ")}\` — ${message}. ` +
        `Returning a synthetic failed result instead of crashing; any gate check ` +
        `depending on this call will fail-open with that result (see the gate's own ` +
        `fail-open warning, if any, for which check was skipped).`
    );
    return {
      exitCode: 127, // conventional shell "command not found" exit code
      stdout: "",
      stderr: `spawn failed: ${message}`,
      timedOut: false,
    };
  }
}

/**
 * Standard-location fallbacks for `git`, tried when `Bun.which` can't
 * resolve it from the (PATH-augmented) spawn environment. Checked with
 * `existsSync` — no subprocess spawn, so this step can never itself throw
 * ENOENT. Covers macOS Homebrew (Apple Silicon `/opt/homebrew`, Intel
 * `/usr/local`), Xcode Command Line Tools / system git, and the common
 * Linux distro location.
 */
const GIT_FALLBACK_PATHS: readonly string[] = [
  "/opt/homebrew/bin/git",
  "/usr/local/bin/git",
  "/usr/bin/git",
  "/bin/git",
];

/**
 * Module-level cache — git-binary resolution doesn't change mid-process.
 * Only a SUCCESSFUL resolution is ever cached (mt#2810 PR #1952 R1
 * NON-BLOCKING): caching a failed ("nothing resolved") attempt would
 * permanently lock the process into re-spawning bare `"git"` even if
 * whatever made resolution fail (e.g. a not-yet-mounted filesystem, a PATH
 * that gets repaired mid-process) is no longer true by the next call. Never
 * holds `null` — an unresolved state is represented by `undefined` so every
 * call retries full resolution until one succeeds.
 */
let cachedGitBinaryPath: string | undefined;

export interface ResolveGitBinaryOptions {
  /** Override the PATH string passed to `Bun.which` (tests only). */
  pathOverride?: string;
  /** Override the fallback candidate list (tests only). */
  fallbackPaths?: readonly string[];
  /** Override `existsSync` (tests only — simulate "nothing found"). */
  existsSyncFn?: (path: string) => boolean;
  /** Override `Bun.which` (tests only). */
  whichFn?: (command: string, options?: { PATH?: string }) => string | null;
  /** Bypass the module-level cache (tests only — production always caches). */
  noCache?: boolean;
}

/**
 * Resolve an absolute path to the `git` binary, robust to a hook spawn
 * environment whose PATH doesn't include it (mt#2810 fix #2 — see the
 * module comment above for the root-cause finding this replaces).
 *
 * Resolution order:
 *   1. `Bun.which("git", { PATH: <augmented PATH> })` — respects whatever
 *      real PATH customization is present (Homebrew, asdf, nix, etc.)
 *   2. `GIT_FALLBACK_PATHS`, checked via `existsSync` (no subprocess).
 *   3. Bare `"git"` as a last resort — spawning this can still fail if
 *      truly nothing resolves, but `safeSpawnSync` (above) now catches
 *      that failure instead of letting it crash the hook process.
 *
 * Cached for the lifetime of the hook process.
 */
export function resolveGitBinary(options: ResolveGitBinaryOptions = {}): string {
  if (!options.noCache && cachedGitBinaryPath) {
    return cachedGitBinaryPath;
  }
  const pathPrefix =
    options.pathOverride ?? `/opt/homebrew/bin:/usr/local/bin:${process.env.PATH ?? ""}`;
  const which =
    options.whichFn ?? ((cmd: string, opts?: { PATH?: string }) => Bun.which(cmd, opts));
  const exists = options.existsSyncFn ?? existsSync;
  const fallbacks = options.fallbackPaths ?? GIT_FALLBACK_PATHS;

  let resolved: string | null = null;
  try {
    resolved = which("git", { PATH: pathPrefix });
  } catch {
    resolved = null;
  }
  if (!resolved) {
    for (const candidate of fallbacks) {
      try {
        if (exists(candidate)) {
          resolved = candidate;
          break;
        }
      } catch {
        // Treat a filesystem-check error as "not found" — keep scanning.
      }
    }
  }
  // Only a successful resolution is cached — see the `cachedGitBinaryPath`
  // doc comment above (mt#2810 PR #1952 R1 NON-BLOCKING).
  if (!options.noCache && resolved) cachedGitBinaryPath = resolved;
  return resolved ?? "git";
}

/**
 * Test-only: reset the module-level git-binary resolution cache. Production
 * code never needs this — the cache is meant to persist for the hook
 * process's lifetime. Exists so tests can deterministically exercise the
 * cache-miss path without depending on ambient state from other tests or
 * production code paths that may have already populated the cache earlier
 * in the same test-runner process.
 */
export function __resetGitBinaryCacheForTests(): void {
  cachedGitBinaryPath = undefined;
}

/**
 * Resolve the pinned TypeScript checker for a project root (mt#3657).
 *
 * Returns the local `node_modules/.bin/tsgo` when it exists, else null. There is deliberately
 * NO `bunx @typescript/native-preview` fallback: that command does not run the pinned
 * dependency — the package's bin is `tsgo`, so bunx's package-name lookup misses and it
 * fetches `@latest` into a temp dir instead. Measured 2026-08-04: pinned
 * `7.0.0-dev.20260419.1` vs bunx's `7.0.0-dev.20260707.2`, three months apart, and the
 * download racing the check in one invocation is what produced the SIGKILLs.
 *
 * Null means the caller should SKIP rather than substitute — these hooks are informational,
 * so a missing install must not become a wall of phantom errors about the operator's code.
 *
 * Mirrors {@link resolveGitBinary}'s shape (resolution + injectable existence check). The
 * src-side sibling is `src/utils/tsgo-binary.ts`; the two are stated separately because hook
 * files cannot import from `src/`.
 */
export function resolveTsgoBinary(
  projectRoot: string,
  existsSyncFn: (path: string) => boolean = existsSync
): string | null {
  const candidate = `${projectRoot}/node_modules/.bin/tsgo`;
  try {
    return existsSyncFn(candidate) ? candidate : null;
  } catch {
    return null;
  }
}

/**
 * Substitute `cmd[0]` with the resolved absolute git path when the command
 * invokes `git` by bare name. No-op for any other command (e.g. `gh`).
 */
function resolveGitCommand(cmd: string[]): string[] {
  if (cmd[0] !== "git") return cmd;
  return [resolveGitBinary(), ...cmd.slice(1)];
}

// Sync exec helper — returns exit code + output without throwing.
// `spawnSyncImpl`/`onDegraded` on `options` are test-only DI (mt#3630).
export function execSync(cmd: string[], options?: ExecOptions): ExecResult {
  return safeSpawnSync(resolveGitCommand(cmd), {
    cwd: options?.cwd,
    timeout: options?.timeout,
    ...execInjection(options),
  });
}

/**
 * Fail-fast Postgres connect for hook-shelled `minsky` CLI calls (mt#2982).
 *
 * Every guard that shells the minsky CLI runs under a hard spawn-kill budget
 * (4-8s across consumers), while the CLI's default postgres-js connect_timeout
 * is 10s — so a hanging/reconnecting DB always loses the race to the kill and
 * surfaces as an empty-output "unparseable" failure (the mt#2982 confirmed
 * diagnosis). Injecting a 2s connect timeout keeps the worst case (bundle boot
 * ~1s + embed ~1s + connect-fail 2s) inside every consumer budget and turns
 * the failure into a fast, clearly attributed error (postgres-js
 * CONNECT_TIMEOUT) that the guards' existing stderr surfacing reports
 * verbatim. An operator-set value in the parent env wins (spread order in
 * execWithPath). Tradeoff: a healthy-but-slow connect (>2s, degraded-DB
 * window) now fails fast too — for a guard probe that outcome is the same
 * designed fail-open skip the spawn-kill produced, minus the hang and the
 * vague signature. Non-minsky spawns (git/gh) ignore the variable; injecting
 * it unconditionally keeps this a single-choke-point change.
 */
export const HOOK_MINSKY_CLI_PG_CONNECT_TIMEOUT_SEC = "2";

/**
 * PATH-augmented sync exec helper. Prepends common homebrew/system binary
 * directories to PATH so that `gh` resolves correctly regardless of the
 * shell PATH that launched Claude Code, and additionally resolves `git`
 * robustly via `resolveGitBinary` (mt#2810 — PATH augmentation alone is not
 * a resolution strategy, see the module comment above). Used by hooks that
 * call `gh`/`git`. Never throws — spawn failures degrade to a structured
 * `ExecResult` (see `safeSpawnSync`).
 *
 * `spawnSyncImpl`/`onDegraded` on `options` are test-only DI (mt#3630).
 */
export function execWithPath(cmd: string[], options?: ExecOptions): ExecResult {
  const pathPrefix = `/opt/homebrew/bin:/usr/local/bin:${process.env.PATH ?? ""}`;
  return safeSpawnSync(resolveGitCommand(cmd), {
    cwd: options?.cwd,
    // PRE-EXISTING default, unchanged by mt#3630 (PR #2580 R1 BLOCKING, verified false
    // positive against `git diff main...HEAD`): `?? 10000` is a caller-overridable
    // FALLBACK, not a forced cap, and has been this helper's default since before this
    // refactor. `execSync` deliberately has no default — it is the plain wrapper.
    timeout: options?.timeout ?? 10000,
    env: {
      MINSKY_PERSISTENCE_POSTGRES_CONNECT_TIMEOUT: HOOK_MINSKY_CLI_PG_CONNECT_TIMEOUT_SEC,
      ...process.env,
      PATH: pathPrefix,
    },
    ...execInjection(options),
  });
}

// Read hook input from stdin
export async function readInput<T = ClaudeHookInput>(): Promise<T> {
  const raw = await Bun.stdin.json();
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    normalizeToolResult(raw as Record<string, unknown>);
  }
  return raw as T;
}

/** True for an MCP content block of the form `{type: "text", text: string}`. */
function isTextContentBlock(block: unknown): block is { type: "text"; text: string } {
  return (
    !!block &&
    typeof block === "object" &&
    (block as { type?: unknown }).type === "text" &&
    typeof (block as { text?: unknown }).text === "string"
  );
}

/** Parse `text` as JSON and assign to `tool_result` when it yields an object; fail-open. */
function assignParsedJsonResult(payload: Record<string, unknown>, text: string): void {
  try {
    const parsed: unknown = JSON.parse(text);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      payload["tool_result"] = parsed as Record<string, unknown>;
    }
  } catch {
    // Non-JSON text result (plain prose output) — leave untouched.
  }
}

/**
 * Normalize the measured PostToolUse payload shape onto the `tool_result` key this repo's
 * hooks read (mt#3308). Production sends `tool_response`, never `tool_result`:
 *
 *   - Native tools (e.g. `Agent`): `tool_response` is already a parsed object — copied over
 *     directly.
 *   - MCP tools (`mcp__*`): `tool_response` is the MCP content envelope
 *     `[{type:"text", text:"<json>"}]` with the tool's JSON result STRINGIFIED in the first
 *     text block — unwrapped and parsed.
 *   - A raw JSON-string `tool_response` (not observed in captures, but cheap to accept) is
 *     parsed the same way (PR #2402 R1).
 *
 * Before this normalization, every PostToolUse reader gating on `tool_result` contents was
 * silently dead or degraded against production payloads (mt#3182's stamp hook wrote 0 rows in
 * 235 sessions; the drive-pr-to-convergence reminder never fired). Fail-open by design: an
 * absent/unparseable `tool_response` leaves the payload untouched, an already-usable
 * `tool_result` (e.g. a hand-built test payload) is never overwritten, and non-PostToolUse
 * payloads are never mutated at all (PR #2402 R1).
 */
export function normalizeToolResult(payload: Record<string, unknown>): void {
  if (payload["hook_event_name"] !== "PostToolUse") return;

  const existing = payload["tool_result"];
  if (existing && typeof existing === "object" && !Array.isArray(existing)) return;

  const response = payload["tool_response"];
  if (!response) return;

  if (typeof response === "string") {
    assignParsedJsonResult(payload, response);
    return;
  }

  if (typeof response === "object" && !Array.isArray(response)) {
    payload["tool_result"] = response;
    return;
  }

  if (Array.isArray(response)) {
    const textBlock = response.find(isTextContentBlock);
    if (!textBlock) return;
    assignParsedJsonResult(payload, textBlock.text);
  }
}

/** A spawned process handle — the only member `emitHookFiredOnDeny` touches. */
export interface SpawnedProcessLike {
  unref(): void;
}

/** Options `emitHookFiredOnDeny` hands to its spawn impl. */
export interface SpawnCallOptions {
  stdout: "ignore";
  stderr: "ignore";
  stdin: "ignore";
  env: SpawnEnv;
}

/**
 * An injectable stand-in for `Bun.spawn` (mt#3630) — same rationale as
 * {@link SpawnSyncImpl}: production always uses the real one, tests pass a fake rather
 * than patching the global.
 */
export type SpawnImpl = (cmd: string[], options: SpawnCallOptions) => SpawnedProcessLike;

/** Test-only injection points for the stdout/telemetry side (mt#3630). */
export interface WriteOutputInjection {
  /** Injectable `Bun.spawn` — production defaults to the real one. */
  spawnImpl?: SpawnImpl;
  /** Injectable stdout writer — production defaults to `process.stdout.write`. */
  writeImpl?: (chunk: string) => boolean;
}

// Write hook output to stdout.
// `deps` is test-only DI (mt#3630); all ~54 production call sites pass one argument.
export function writeOutput(output: HookOutput, deps?: WriteOutputInjection): void {
  const write = deps?.writeImpl ?? ((chunk: string) => process.stdout.write(chunk));
  write(JSON.stringify(output));
  emitHookFiredOnDeny(output, deps);
}

/**
 * Ceiling multiplier for a preference-class override, relative to the guard's
 * shipped default (PR #2526 R1). An override is a TUNE, not an off switch: a
 * value far above the default silently disables the guard, which is the same
 * outcome as the dedicated `MINSKY_SKIP_*` var but without the audit trail
 * that makes a disabled guard visible. 10x is wide enough for any legitimate
 * re-tune (a 200-word budget → 2000 words is already well past any real
 * report) while keeping a typo'd extra zero from reading as intent.
 *
 * Deliberately NOT a per-var absolute bound: the ceiling scales with whatever
 * default the guard ships, so a future preference threshold gets a sane bound
 * for free rather than needing its own constant.
 */
export const PREFERENCE_OVERRIDE_MAX_MULTIPLE = 10;

/**
 * Read a positive-integer tuning value from the environment, falling back to
 * the shipped default on absence, non-numeric input, a non-positive value, or
 * a value above {@link PREFERENCE_OVERRIDE_MAX_MULTIPLE}x the default
 * (mt#3518). This is the config channel for PREFERENCE-class guard thresholds
 * (`tuningOwnership: "preference"` in the registry): the shipped constant is
 * the vendor default every project inherits; the env var is the local
 * override. Fail-open to the default — a malformed or out-of-range override
 * must never break a guard, and must never silently disable one.
 *
 * To turn a guard OFF, use its `MINSKY_SKIP_*` / `MINSKY_HOOK_OVERRIDE`
 * channel, which is what the audit trail reads.
 */
export function readPositiveIntEnv(
  envVarName: string,
  defaultValue: number,
  env: Record<string, string | undefined> = process.env
): number {
  const raw = env[envVarName];
  if (raw === undefined || raw.trim() === "") return defaultValue;
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed <= 0) return defaultValue;
  if (parsed > defaultValue * PREFERENCE_OVERRIDE_MAX_MULTIPLE) return defaultValue;
  return parsed;
}

/**
 * Resolve a preference-class threshold across all three sources (mt#3581).
 *
 * Precedence, highest first:
 *
 *   1. **An explicit `MINSKY_*` env var.** A human typed a number; an
 *      automatic tune must never silently overrule that. This is the one
 *      ordering choice in the chain that is a real decision rather than a
 *      consequence — the alternative (tuned value wins) would make an
 *      operator's explicit setting quietly stop working, with no surface
 *      that says so.
 *   2. **A locally-tuned value** from `guard-tuning-store.ts` — applied
 *      either by consent or by the customer's own preference expression.
 *   3. **The shipped default** compiled into the guard.
 *
 * The tuned value is bounds-checked on the way OUT as well as on the way in:
 * the store only accepts positive integers, and this re-applies the same
 * {@link PREFERENCE_OVERRIDE_MAX_MULTIPLE} ceiling the env path enforces, so
 * a store hand-edited past the bound degrades to the default rather than
 * taking effect. Trusting the writer would make the ceiling advisory.
 *
 * Reads are fail-open by way of the store's own posture: an unreadable or
 * malformed store yields no tuned value, and the guard runs on its default.
 */
export function readTunedThreshold(
  envVarName: string,
  defaultValue: number,
  deps: {
    env?: Record<string, string | undefined>;
    readTunedValueFn?: (thresholdKey: string) => number | undefined;
  } = {}
): number {
  const env = deps.env ?? process.env;

  const raw = env[envVarName];
  if (raw !== undefined && raw.trim() !== "") {
    return readPositiveIntEnv(envVarName, defaultValue, env);
  }

  const tuned = deps.readTunedValueFn?.(envVarName);
  if (
    tuned !== undefined &&
    Number.isInteger(tuned) &&
    tuned > 0 &&
    tuned <= defaultValue * PREFERENCE_OVERRIDE_MAX_MULTIPLE
  ) {
    return tuned;
  }

  return defaultValue;
}

// ---------------------------------------------------------------------------
// hook.fired system-event bridge (mt#2537)
// ---------------------------------------------------------------------------
//
// Design (chosen over touching each individual guard hook, per mt#2537's
// "prefer a design touching few/no individual guard hooks" preference):
// `writeOutput` is the single common function every guard hook (54 call sites
// as of mt#2537) already calls to emit its stdout decision. Intercepting HERE
// gives `hook.fired` coverage across every hook with zero per-hook edits.
//
// Scope: only `decision: "blocked"` (a `permissionDecision: "deny"`) is
// covered in v1. "overridden" decisions (MINSKY_FORCE_*/MINSKY_SKIP_* env-var
// bypasses) are surfaced by each guard as its own free-text audit line on
// `GuardOutcome.auditLines` (e.g. "[block-secret-file-read] OVERRIDE: ..."),
// which the dispatcher writes to STDERR (dispatcher.ts's `stderrWrite` loop).
// A guard must never write to stdout: Claude Code discards a hook's ENTIRE
// output when stdout carries anything besides the single JSON object, which
// silently voids even a different guard's `deny` (mt#3625). There is still no
// shared choke point for override lines the way there is for `writeOutput`'s
// JSON contract, and retrofitting every override call site would violate the
// touch-few-hooks design preference. Deferred; see mt#2537 PR body.
//
// Invocation path: fire-and-forget, detached `minsky events emit hook.fired`
// subprocess, `.unref()`'d immediately so the parent hook process's own exit
// (and its <15s host-cap budget, see readHostCap above) is never blocked on
// it. Any failure (spawn error, `minsky` not on PATH) is swallowed — this
// must never affect the hook's actual permission decision, which has already
// been written to stdout by the time this runs.
export function emitHookFiredOnDeny(
  output: HookOutput,
  deps?: Pick<WriteOutputInjection, "spawnImpl">
): void {
  if (output.hookSpecificOutput?.permissionDecision !== "deny") return;
  const spawnImpl: SpawnImpl = deps?.spawnImpl ?? ((cmd, options) => Bun.spawn(cmd, options));
  try {
    const scriptPath = process.argv[1] ?? "unknown";
    const hookName = scriptPath.split(/[\\/]/).pop() || scriptPath;
    const payload = JSON.stringify({ hook: hookName, decision: "blocked" as const });
    // Same PATH-augmentation convention as execWithPath above (macOS/Linux
    // homebrew + local-bin prefixes). Minsky's hook toolchain is macOS/Linux-
    // only today (no Windows path-separator handling); if Windows support is
    // ever added, both helpers need updating together.
    const pathPrefix = `/opt/homebrew/bin:/usr/local/bin:${process.env.PATH ?? ""}`;
    const proc = spawnImpl(["minsky", "events", "emit", "hook.fired", "--payload", payload], {
      stdout: "ignore",
      stderr: "ignore",
      stdin: "ignore",
      env: {
        MINSKY_PERSISTENCE_POSTGRES_CONNECT_TIMEOUT: HOOK_MINSKY_CLI_PG_CONNECT_TIMEOUT_SEC,
        ...process.env,
        PATH: pathPrefix,
      },
    });
    proc.unref();
  } catch {
    // Best-effort — telemetry must never break (or delay) the hook's actual
    // decision, which writeOutput has already flushed to stdout above.
  }
}

// ---------------------------------------------------------------------------
// Host-cap reader + budget derivation (mt#1546)
// ---------------------------------------------------------------------------
//
// PreToolUse/PostToolUse hooks declare a host-imposed `timeout` in
// `.claude/settings.json` — Claude Code SIGKILLs the hook after that many
// seconds. Hooks that run multiple bounded calls inside that window need their
// internal budgets to stay under the cap. Hardcoding ms values per-hook drifts
// silently when the cap is bumped; reading the cap at startup keeps the
// relationship structural.
//
// `readHostCap` walks `hooks.<event>[*].hooks[*].command` for the entry that
// references this hook's basename (exact or `<dir>/<basename>` suffix match) and
// returns its `timeout` field. Callers pass an optional `events` filter to
// disambiguate when the same hook is wired into more than one event.

import { readFileSync } from "node:fs";
import { join } from "node:path";

export const DEFAULT_HOST_CAP_SEC = 15;

/**
 * Canary-mode gate (mt#3004, PR #2145 R1). Set to "1" ONLY by the canary
 * runner (`scripts/run-guard-canaries.ts`) and by unit tests. The test-only
 * seams that alter guard behavior via env (memory-search's fixture stub,
 * the daemon-staleness tracker-home redirect) are honored ONLY when this
 * gate is active — a production process with one of those vars set but no
 * canary mode behaves exactly as before. Shared here (not in
 * canary-runner.ts) so guard modules can import it without a
 * guard -> canary-runner -> registry -> guard import cycle.
 */
export const CANARY_MODE_ENV = "MINSKY_CANARY_MODE";

/**
 * Floor on derived per-call timeouts. Without a clamp, hostCaps in the
 * single-digit seconds (or pathologically small values) can floor to 0 or
 * a few ms, which is shorter than realistic git-call wall time and would
 * make every probe instantly time out. 100ms is well below the typical
 * git-probe latency (<= a few hundred ms in degraded conditions) but above
 * the noise floor for spawn + exit overhead.
 */
export const MIN_DERIVED_BUDGET_MS = 100;

export interface HostCapInfo {
  /** Resolved host cap in seconds. */
  hostCapSec: number;
  /** Where the cap came from. */
  source: "settings.json" | "default";
  /**
   * Set on every fallback path (project dir undetectable, settings.json missing
   * or malformed, no matcher entry, missing/invalid timeout). Unset on the
   * happy path. Hooks should surface the warning through their existing
   * operator-warning channel (e.g., the `warnings` array emitted as
   * `additionalContext`).
   */
  warning?: string;
}

/**
 * Read the host-imposed timeout cap (in seconds) for the matcher entry that
 * runs this hook.
 *
 * @param hookFilename — basename of the hook script (e.g.,
 *   `"check-branch-fresh.ts"`). Matched against each hook entry's `command`
 *   field via exact equality OR `<dir>/<basename>` suffix match (so the typical
 *   `$CLAUDE_PROJECT_DIR/.claude/hooks/<basename>` form is recognised).
 *   Substring match was deliberately replaced with suffix match in PR #958
 *   R1 to disambiguate when multiple hooks share a filename suffix.
 * @param projectDir — optional override. When omitted, falls back to
 *   `process.env.CLAUDE_PROJECT_DIR`.
 * @param options — `events` allowlist defaults to `["PreToolUse"]` so
 *   callers don't have to remember the safer default; pass a different
 *   array (or `[]` for "all events") when the hook fires on a different
 *   lifecycle event. `readFile` defaults to `node:fs.readFileSync`; tests
 *   inject a fake reader to keep tests pure.
 *
 * Falls back to `DEFAULT_HOST_CAP_SEC` (15s) on any failure path with a
 * descriptive `warning` set.
 */
export interface ReadHostCapOptions {
  /**
   * Restrict the walk to these event names. Defaults to `["PreToolUse"]`
   * (the typical case). Pass `[]` to scan every event or a different array
   * for PostToolUse/Stop/etc. hooks. The default makes the function
   * footgun-free for the common case (PR #958 R2 NON-BLOCKING #3 fix).
   */
  events?: readonly string[];
  /** Custom file reader (used by tests to avoid touching real fs). */
  readFile?: (path: string) => string;
}

export function readHostCap(
  hookFilename: string,
  projectDir?: string,
  options?: ReadHostCapOptions
): HostCapInfo {
  const readFile = options?.readFile ?? ((p: string): string => readFileSync(p, "utf8") as string);
  const events = options?.events ?? ["PreToolUse"];
  const root = projectDir ?? process.env["CLAUDE_PROJECT_DIR"] ?? null;
  if (!root) {
    return {
      hostCapSec: DEFAULT_HOST_CAP_SEC,
      source: "default",
      warning: `CLAUDE_PROJECT_DIR not set and no projectDir override — using default host cap (${DEFAULT_HOST_CAP_SEC}s)`,
    };
  }

  const settingsPath = join(root, ".claude", "settings.json");
  let raw: string;
  try {
    raw = readFile(settingsPath);
  } catch (err) {
    return {
      hostCapSec: DEFAULT_HOST_CAP_SEC,
      source: "default",
      warning: `Could not read ${settingsPath}: ${err instanceof Error ? err.message : String(err)} — using default host cap (${DEFAULT_HOST_CAP_SEC}s)`,
    };
  }

  return findHostCapInSettings(raw, hookFilename, {
    events,
    settingsPathForErrors: settingsPath,
  });
}

/**
 * True iff `command` references a hook whose script basename equals
 * `hookFilename`. Accepts:
 *   - exact equality (`command === hookFilename`)
 *   - `<dir>/<basename>` path-segment suffix on any whitespace-delimited
 *     token in `command`
 *
 * Tokenising on whitespace lets the matcher recognise wrapper invocations
 * (`bun run .claude/hooks/check-branch-fresh.ts --flag`,
 * `node $CLAUDE_PROJECT_DIR/.claude/hooks/check-branch-fresh.ts`) AND
 * trailing-args invocations (`.claude/hooks/check-branch-fresh.ts --quiet`)
 * — PR #958 R3 BLOCKING #1 fix.
 *
 * Rejects substrings that don't end at a path-segment boundary, so e.g.
 * `"fresh.ts"` does NOT match `"check-branch-fresh.ts"` and
 * `"check-branch-fresh.ts"` does NOT match `"check-branch-fresh.ts.bak"`.
 *
 * Cross-platform: backslash-separated paths in tokens (Windows-style,
 * e.g., `C:\repo\.claude\hooks\check-branch-fresh.ts`) are normalised to
 * forward slashes before the suffix check.
 *
 * Case-sensitive (intentional — a casing typo in `settings.json` should
 * fail loudly with a "no matcher entry found" warning, not silently match
 * the wrong entry). Reaffirmed against R2 NON-BLOCKING #4 and R3
 * NON-BLOCKING #3.
 */
// Known runtime wrappers that may precede the hook script in `command`.
// When found at the head, the wrapper (and its subcommand, if any) is
// skipped before evaluating the executable token. This handles invocations
// like `bun run X`, `node X`, `npx tsx X`, etc. PR #958 R6 BLOCKING fix.
const KNOWN_WRAPPERS: ReadonlySet<string> = new Set([
  "env",
  "bun",
  "bunx",
  "node",
  "npx",
  "tsx",
  "ts-node",
  "deno",
]);

// Wrappers that take a subcommand before the script (e.g., `bun run X`,
// `deno run X`). When the wrapper matches, the subcommand is also skipped
// so the executable token resolves to the script path.
const KNOWN_WRAPPER_SUBCOMMANDS: Readonly<Record<string, ReadonlySet<string>>> = {
  bun: new Set(["run", "x"]),
  deno: new Set(["run"]),
};

// Pattern for `NAME=value` env var assignments at the head of a command
// (e.g., `FOO=1 BAR=2 bun run X` or `env FOO=1 X`). PR #958 R6 BLOCKING
// fix.
const ENV_VAR_ASSIGNMENT_RE = /^[A-Z_][A-Z_0-9]*=/;

/**
 * Locate the executable token in a tokenised command — i.e., the first
 * token that is neither a `NAME=value` env-var assignment nor a known
 * wrapper (with optional subcommand). This is the only token whose
 * basename is checked against the hook filename — arguments after it are
 * never considered, which prevents false-positive matches from arg values
 * that happen to end with the hook's basename (PR #958 R5 + R6).
 */
function findExecutableToken(tokens: readonly string[]): string | null {
  let i = 0;
  while (i < tokens.length) {
    const t = tokens[i] as string;
    if (ENV_VAR_ASSIGNMENT_RE.test(t)) {
      i++;
      continue;
    }
    if (KNOWN_WRAPPERS.has(t)) {
      const wrapper = t;
      i++;
      const subs = KNOWN_WRAPPER_SUBCOMMANDS[wrapper];
      if (subs && i < tokens.length && subs.has(tokens[i] as string)) {
        i++;
      }
      continue;
    }
    break;
  }
  return tokens[i] ?? null;
}

function commandMatchesHookFile(command: string, hookFilename: string): boolean {
  if (command === hookFilename) return true;
  // Tokenise on whitespace, then resolve the executable token by skipping
  // leading env-var assignments and known wrappers. Only that one token's
  // basename is checked. This rejects:
  //   - argument values that end with the hook basename (false positive)
  //   - non-executable strings in args (e.g., `echo X` — `echo` is not a
  //     wrapper so it becomes the exec token, doesn't match)
  // and accepts:
  //   - bare paths, wrapper invocations (`bun run X`, `node X`), env-prefix
  //     forms (`FOO=1 bun run X`, `env FOO=1 X`), quoted paths.
  const tokens = command.split(/\s+/).filter((t) => t.length > 0);
  const execToken = findExecutableToken(tokens);
  if (execToken === null) return false;
  const dequoted = execToken.replace(/^['"]|['"]$/g, "");
  const normalised = dequoted.replace(/\\/g, "/");
  if (normalised === hookFilename) return true;
  if (normalised.endsWith(`/${hookFilename}`)) return true;
  return false;
}

interface FindHostCapOptions {
  events?: readonly string[];
  settingsPathForErrors?: string;
}

/**
 * Pure JSON-walker: given the contents of `.claude/settings.json` (already
 * read from disk), find the matcher entry whose `command` matches
 * `hookFilename` (exact or `<dir>/<basename>` suffix) and return its `timeout`.
 *
 * Split out from `readHostCap` so tests can exercise the parse + walk +
 * validate paths without touching the real filesystem.
 */
export function findHostCapInSettings(
  raw: string,
  hookFilename: string,
  options: FindHostCapOptions = {}
): HostCapInfo {
  const settingsPathForErrors = options.settingsPathForErrors ?? ".claude/settings.json";
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return {
      hostCapSec: DEFAULT_HOST_CAP_SEC,
      source: "default",
      warning: `Could not parse ${settingsPathForErrors}: ${err instanceof Error ? err.message : String(err)} — using default host cap (${DEFAULT_HOST_CAP_SEC}s)`,
    };
  }

  // Walk hooks.<event>[*].hooks[*].command. Settings shape:
  //   { hooks: { PreToolUse: [{ matcher, hooks: [{ command, timeout }] }] } }
  const settings = parsed as { hooks?: Record<string, unknown> };
  const allEvents = settings.hooks ?? {};
  // Empty array means "no filter" (scan all events) — the safer way to
  // express "any event" without conflating it with the default-PreToolUse
  // shorthand. Undefined also means "no filter" for backwards compat.
  const eventFilter = options.events && options.events.length > 0 ? options.events : null;
  for (const [eventName, eventEntries] of Object.entries(allEvents)) {
    if (eventFilter && !eventFilter.includes(eventName)) continue;
    if (!Array.isArray(eventEntries)) continue;
    for (const matcherEntry of eventEntries) {
      if (!matcherEntry || typeof matcherEntry !== "object") continue;
      const matcher = matcherEntry as { hooks?: unknown };
      if (!Array.isArray(matcher.hooks)) continue;
      for (const hookDef of matcher.hooks) {
        if (!hookDef || typeof hookDef !== "object") continue;
        const def = hookDef as { type?: unknown; command?: unknown; timeout?: unknown };
        // Settings.json supports a `type` discriminator on hooks ("command"
        // is the only one shipping today). Require an exact match so future
        // schema additions don't let a non-command entry's `command`-shaped
        // field misattribute a timeout (PR #958 R5 NON-BLOCKING #3).
        if (def.type !== "command") continue;
        if (typeof def.command !== "string") continue;
        if (!commandMatchesHookFile(def.command, hookFilename)) continue;
        if (typeof def.timeout !== "number" || !Number.isFinite(def.timeout) || def.timeout <= 0) {
          return {
            hostCapSec: DEFAULT_HOST_CAP_SEC,
            source: "default",
            warning: `Settings entry for ${hookFilename} has missing/invalid timeout — using default host cap (${DEFAULT_HOST_CAP_SEC}s)`,
          };
        }
        return { hostCapSec: def.timeout, source: "settings.json" };
      }
    }
  }

  return {
    hostCapSec: DEFAULT_HOST_CAP_SEC,
    source: "default",
    warning: `No matcher entry found referencing ${hookFilename} — using default host cap (${DEFAULT_HOST_CAP_SEC}s)`,
  };
}

// ---------------------------------------------------------------------------
// Budget derivation (shared util — mt#1546)
// ---------------------------------------------------------------------------
//
// Three timer constants govern hook wall-clock behaviour. They derive from
// the host-imposed `timeout` field via the ratios below. Future hooks with
// the same constraint reuse `deriveBudgets` from this util — no need to
// re-export the ratios from each hook module.

/**
 * Fraction of the host cap allocated to a hook's overall wall-clock budget.
 * The remaining 40% is headroom for process startup, stdout writes, OS
 * scheduling jitter, and a final-call overrun under the budget guard.
 */
export const OVERALL_BUDGET_RATIO = 0.6;

/**
 * Fraction of the overall budget granted to the network-bound `git fetch`.
 * Fetch dominates worst-case wall time and is the only off-host call.
 */
export const FETCH_TIMEOUT_RATIO = 0.55;

/**
 * Fraction of the overall budget granted to each local git probe. ~1/6 means
 * up to 6 sequential probes can run within budget.
 */
export const GIT_TIMEOUT_RATIO = 0.17;

export interface DerivedBudgets {
  /** Overall wall-clock budget for the hook (incl. fetch). */
  overallBudgetMs: number;
  /** Per-call timeout for the network-bound `git fetch`. */
  fetchTimeoutMs: number;
  /** Per-call timeout for fast local git operations. */
  gitTimeoutMs: number;
}

/**
 * Derive ms-valued budgets from a host cap (in seconds). Pure function.
 *
 * Each derived value is clamped to `MIN_DERIVED_BUDGET_MS` (100ms) so that
 * pathologically small host caps don't produce zero-or-near-zero per-call
 * budgets that every probe would instantly exceed. For realistic caps
 * (>= 5s) the clamp never fires.
 */
export function deriveBudgets(hostCapSec: number): DerivedBudgets {
  const overallBudgetMs = Math.max(
    MIN_DERIVED_BUDGET_MS,
    Math.floor(hostCapSec * 1000 * OVERALL_BUDGET_RATIO)
  );
  return {
    overallBudgetMs,
    fetchTimeoutMs: Math.max(
      MIN_DERIVED_BUDGET_MS,
      Math.floor(overallBudgetMs * FETCH_TIMEOUT_RATIO)
    ),
    gitTimeoutMs: Math.max(MIN_DERIVED_BUDGET_MS, Math.floor(overallBudgetMs * GIT_TIMEOUT_RATIO)),
  };
}

// ---------------------------------------------------------------------------
// Repo-root resolution (mt#2700 origin, lifted here mt#2710)
// ---------------------------------------------------------------------------
//
// `input.cwd` tracks the harness SHELL's working directory, which is
// routinely a SUBDIRECTORY of the repo (e.g. `<session>/cockpit-tray/
// src-tauri` during a build, or any `cd`'d-into subtree). Subprocess git/gh
// calls (`git -C <dir>`, `gh api ...` with `{ cwd }`) walk up to the repo
// root on their own and stay correct regardless — that class of `input.cwd`
// consumer is explicitly OUT of scope here (see mt#2710 spec). But any hook
// that resolves a REPO-RELATIVE STATE path itself (calibration logs under
// `.minsky/`, baseline/dismissals files, policy-corpus reads) by joining
// `input.cwd` directly needs the actual repo ROOT, not the raw shell cwd —
// otherwise state scatters into a subdirectory's own stray `.minsky/` (mt#2700
// mid-merge probe incident; mt#2710 generalizes the fix to every such
// consumer). `findRepoRoot` was originally implemented locally in
// `check-branch-fresh.ts` (mt#2700) for its own fs-only mid-merge probe; it
// lives here so every `.minsky/hooks/*.ts` guard can share one resolver
// instead of re-deriving it. `check-branch-fresh.ts` now imports and
// re-exports these from here (no behavior change for its own callers or
// tests).
//
// @see mt#2700 — originating fix (check-branch-fresh.ts mid-merge probe)
// @see mt#2710 — this lift + adoption across the affected repo-relative-state hooks

import { dirname, isAbsolute, resolve } from "node:path";
import { statSync } from "node:fs";

/**
 * Minimal fs surface used by repo-root / mid-merge detection. Packaged so
 * tests can inject a mock without touching the real filesystem (per the
 * `no-real-fs-in-tests` lint rule).
 */
export interface MergeDetectFs {
  existsSync: (p: string) => boolean;
  readFileSync: (p: string, encoding: BufferEncoding) => string;
  statSync: (p: string) => { isDirectory: () => boolean; isFile: () => boolean };
}

/**
 * Exported (not just module-private) so `check-branch-fresh.ts` can use it as
 * the default value for its own `detectMergeInProgress`, which stayed in that
 * file (mid-merge-marker detection is specific to the freshness guard, not a
 * general repo-root concern) but shares this fs surface with `resolveGitDir`
 * and `findRepoRoot` below.
 */
export const DEFAULT_FS: MergeDetectFs = {
  existsSync,
  readFileSync: (p, encoding) => readFileSync(p, encoding) as string,
  statSync: (p) => statSync(p),
};

/**
 * Resolve the on-disk git directory for `repoDir`, honoring git's `.git`-as-file
 * indirection convention. Three cases:
 *
 *   1. `<repoDir>/.git` is a directory — return that path (typical clone).
 *   2. `<repoDir>/.git` is a FILE whose contents are `gitdir: <path>` —
 *      parse and return the resolved target (typical `git worktree` checkout
 *      and certain submodule layouts). Relative `<path>` is resolved against
 *      `repoDir` per git's spec.
 *   3. `<repoDir>/.git` is missing or unparseable — fall back to
 *      `<repoDir>/.git` so callers' downstream `existsSync` probes return
 *      false naturally (no exception thrown for the missing-repo case).
 *
 * The fs surface is injectable for test purposes; defaults to real fs.
 *
 * @see mt#1739 — added to support worktree-based session layouts where the
 *   freshness-guard's mid-merge detection would otherwise miss markers
 *   living under the resolved gitdir, reintroducing the deadlock this fix
 *   exists to close. PR #1054 R1 BLOCKING #1.
 */
export function resolveGitDir(repoDir: string, fs: MergeDetectFs = DEFAULT_FS): string {
  const dotGit = join(repoDir, ".git");
  if (!fs.existsSync(dotGit)) {
    return dotGit;
  }
  try {
    if (fs.statSync(dotGit).isDirectory()) {
      return dotGit;
    }
    const content = fs.readFileSync(dotGit, "utf-8");
    const match = content.match(/^gitdir:\s*(.+?)\s*$/m);
    if (match && match[1]) {
      const target = match[1].trim();
      return isAbsolute(target) ? target : resolve(repoDir, target);
    }
  } catch {
    // Fall through — any stat/read error falls back to the conventional path,
    // which callers handle via existsSync returning false.
  }
  return dotGit;
}

/**
 * Resolve the repository ROOT for `startDir`: walk parent directories until
 * one contains a `.git` entry (directory OR `gitdir:`-file — `resolveGitDir`
 * handles the indirection afterwards), falling back to `startDir` when no
 * `.git` exists anywhere up the tree (missing-repo case; downstream probes
 * then fail closed-to-allow exactly as before).
 *
 * Why this exists (mt#2700, generalized mt#2710): a hook that passes
 * `input.cwd` straight into a repo-relative fs read/write treats the harness
 * SHELL's working directory as the repo root, but `input.cwd` is routinely a
 * SUBDIRECTORY of the repo. Subprocess probes (`git -C <dir>`) walk up to
 * the repo root on their own, so callers that ONLY spawn git/gh subprocesses
 * with `{ cwd: input.cwd }` stay correct without this helper — but a bare fs
 * `join(input.cwd, ".minsky/<log>.jsonl")` does NOT walk up, so state
 * silently scatters into a stray subdirectory `.minsky/` (observed
 * 2026-07-08, mt#2675 convergence; generalized across `.minsky/hooks/**`
 * calibration writers and repo-root resolvers by mt#2710).
 *
 * fs-only by design (no subprocess) — cheap enough to call unconditionally
 * from any hook that needs a real repo root. Cost is a few probes per path
 * segment.
 *
 * A candidate directory is accepted ONLY when its `.git` entry is a real
 * git anchor — a DIRECTORY, or a FILE whose `gitdir:` indirection resolves
 * to an existing directory (PR #1851 R1 BLOCKING #2: a stray non-git `.git`
 * file in an ancestor must not stop the walk early, or every downstream
 * consumer runs against a pseudo-root). Invalid candidates are skipped and
 * the walk continues upward.
 */
function isRepoRootCandidate(dir: string, fs: MergeDetectFs): boolean {
  const dotGit = join(dir, ".git");
  if (!fs.existsSync(dotGit)) {
    return false;
  }
  try {
    if (fs.statSync(dotGit).isDirectory()) {
      return true;
    }
    // `.git` is a file — accept only a parseable `gitdir:` indirection
    // (resolveGitDir returns dotGit itself when the file is unparseable)
    // whose target exists and is a directory.
    const resolved = resolveGitDir(dir, fs);
    return resolved !== dotGit && fs.existsSync(resolved) && fs.statSync(resolved).isDirectory();
  } catch {
    // Any stat/read error means this candidate can't be validated — skip it
    // and let the walk continue.
    return false;
  }
}

export function findRepoRoot(startDir: string, fs: MergeDetectFs = DEFAULT_FS): string {
  let dir = resolve(startDir);
  for (;;) {
    if (isRepoRootCandidate(dir, fs)) {
      return dir;
    }
    const parent = dirname(dir);
    if (parent === dir) {
      // Filesystem root reached without finding a repo — fall back to the
      // original directory so callers' downstream probes fail naturally.
      return resolve(startDir);
    }
    dir = parent;
  }
}

/**
 * Resolve the repo root the HOOK INSTALLATION itself lives in, by walking up
 * from this module's own directory rather than from `input.cwd`.
 *
 * `findRepoRoot(input.cwd)` above answers "which repo is the invoking process
 * standing in" — right for a target path the caller supplied, wrong for state
 * and corpus paths that must be the same file on every invocation. `input.cwd`
 * is the harness SHELL's directory, which for a dispatched subagent points at
 * a session workspace, and for a session whose workspace was later cleaned up
 * points at a path with no `.git` anywhere above it. In that second case
 * `findRepoRoot`'s missing-repo fallback returns the start directory itself,
 * so the caller ends up treating an empty leftover directory as a repo root.
 *
 * mt#3393: the policy-coverage detector resolved both its calibration log and
 * its policy corpus that way. 22 calibration logs accumulated outside the main
 * repo (11 under session clones, 11 under cleaned-up session paths the hook
 * recreated a `.minsky/` in), invisible to the coverage-receipt check. Worse,
 * the empty-root case fed an empty corpus to the coverage decision, so every
 * action there recorded `uncovered` — 13 of 13 such records, against `covered`
 * in the real-clone logs — silently biasing the calibration data that decides
 * whether the detector graduates to blocking mode.
 *
 * `import.meta.dir` is stable across all of that: `.minsky/hooks/` and its
 * generated `.claude/hooks/` mirror are both checked into the main workspace,
 * and `.claude/settings.json` invokes the hook through `$CLAUDE_PROJECT_DIR`,
 * so the executing copy always sits inside the repo whose corpus and
 * calibration state the hook is supposed to be reading and writing. Same
 * derivation as `require-session-for-main-workspace-edits.ts`'s
 * `deriveMainWorkspace` (mt#2928); kept here so state-path callers need not
 * import a guard module.
 *
 * `startDir`/`fs` are injectable so tests can verify the resolution without
 * depending on where the test process happens to run.
 */
export function deriveHookRepoRoot(
  startDir: string = import.meta.dir,
  fs: MergeDetectFs = DEFAULT_FS
): string {
  return findRepoRoot(startDir, fs);
}
